// Builds the website's generated files: the in-browser scanner bundle, copies of the report's
// CSS and JS, the map page, and redirects from old demo links.
// Run with `npm run site`. The output in docs/ is committed, since GitHub Pages serves docs/ as is.
import { copyFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { build } from 'esbuild';
import { reportMarkup } from '../src/report.ts';

const out = new URL('../docs/assets/', import.meta.url);
mkdirSync(out, { recursive: true });

await build({
  entryPoints: [new URL('../src/web.ts', import.meta.url).pathname],
  outfile: new URL('scanner.js', out).pathname,
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  banner: { js: '// ripplemap in-browser scanner. Built from src/web.ts by scripts/site.ts. MIT license.' },
});

for (const file of ['report.css', 'report.js']) copyFileSync(new URL(`../assets/${file}`, import.meta.url), new URL(file, out));

const FONTS = `<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700;800&display=swap">`;

const indent = (text: string) => text.replace(/^(?=.)/gm, '  ');
const mapDir = new URL('../docs/map/', import.meta.url);
mkdirSync(mapDir, { recursive: true });
writeFileSync(
  new URL('index.html', mapDir),
  `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ripplemap</title>
<meta name="theme-color" content="#050b08">
<!-- Generated by scripts/site.ts. Edit that, or assets/report.* and docs/assets/map.js. -->
${FONTS}
<link rel="stylesheet" href="../assets/report.css">
<link rel="stylesheet" href="../assets/site.css">
</head>
<body>
<div class="scan" id="scan">
  <div class="term">
    <div class="term-bar"><i></i><i></i><i></i><span><a href="../">ripplemap</a></span></div>
    <pre id="log" aria-live="polite"></pre>
    <div class="token" id="token" hidden>
      <p id="token-why"></p>
      <p>Paste a GitHub token to get 5,000 an hour. A <a href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener">fine-grained token</a> with no permissions added is enough for public repos. It stays in this tab and is only sent to api.github.com.</p>
      <form class="row" id="token-form" autocomplete="off">
        <input id="token-input" type="password" placeholder="github_pat_…" aria-label="GitHub token" spellcheck="false">
        <button type="submit">scan ▸</button>
      </form>
      <p class="alt">Or <a href="../#explore">open a pre-scanned org</a>, or run <code>npx ripplemap scan --org ORG</code> on your machine. <a href="#" id="forget-token">Forget token</a></p>
    </div>
  </div>
</div>
<template id="report-shell">
${indent(reportMarkup('', 0))}
</template>
<script type="module" src="../assets/map.js"></script>
</body>
</html>
`,
);

// Links shared before the map page existed: demo/<org>/#repo=... now opens map/?org=<org>#repo=...
for (const org of ['linuxserver', 'cloudposse']) {
  const dir = new URL(`../docs/demo/${org}/`, import.meta.url);
  mkdirSync(dir, { recursive: true });
  writeFileSync(
    new URL('index.html', dir),
    `<!doctype html>
<meta charset="utf-8">
<title>ripplemap · ${org}</title>
<meta name="robots" content="noindex">
<script>location.replace('../../map/?org=${org}' + location.hash);</script>
<a href="../../map/?org=${org}">Open the ${org} map</a>
`,
  );
}
console.log('Built docs/assets (scanner.js, report.css, report.js), docs/map/index.html, docs/demo redirects');
